async function fetchTfLCameras() {
  try {
    const res = await stealthFetch("https://api.tfl.gov.uk/Place/Type/JamCam", { signal: AbortSignal.timeout(12e3) });
    if (!res.ok) return [];
    const data = await res.json();
    return (data || []).map((cam) => {
      const imgProp = cam.additionalProperties?.find((p) => p.key === "imageUrl");
      const camId = cam.id?.replace("JamCams_", "") || "";
      return {
        id: `tfl-${cam.id}`,
        lat: cam.lat,
        lng: cam.lon,
        name: cam.commonName || "London JamCam",
        city: "London",
        country: "UK",
        feed_url: imgProp?.value || `https://s3-eu-west-1.amazonaws.com/jamcams.tfl.gov.uk/${camId}.jpg`,
        source: "TfL"
      };
    }).filter((c) => c.lat && c.lng);
  } catch (e) {
    return [];
  }
}
